import{_ as e,f as t,t as n}from"./jsx-runtime-Dy-C9v4B.js";import{n as r,t as i}from"./index-C5MGo52M.js";import{n as a,t as o}from"./Reveal-BDScyaMm.js";var s=e(t(),1),c={section:`_section_1gi17_5`,head:`_head_1gi17_17`,list:`_list_1gi17_35`,item:`_item_1gi17_51`,itemOpen:`_itemOpen_1gi17_67`,question:`_question_1gi17_75`,chevron:`_chevron_1gi17_103`,answerInner:`_answerInner_1gi17_125`,answer:`_answer_1gi17_125`},l=n(),u=[{q:`Do I need coding experience to join?`,a:`No. The program starts from absolute fundamentals — HTML, CSS, and basic programming logic. Most of our students come from non-coding backgrounds. All you need is basic computer literacy and a strong willingness to learn.`},{q:`What is the placement assistance process?`,a:`From month 9 onward, our placement cell works with you on resume building, LinkedIn optimization, mock technical interviews, and HR round preparation. We then introduce you to companies in our growing hiring network and support you through interviews until you receive an offer. We commit to the process — outcomes depend on your performance in company interviews.`},{q:`Is EMI available?`,a:`Yes — no-cost EMI is available, letting you split the program fee into monthly installments with zero interest. Our counsellors will help you pick a plan during enrollment.`},{q:`What is the class schedule?`,a:`Classes run Monday to Saturday with morning and evening batch options. Each session is around 2 hours of live instruction, plus lab/practice time. Weekend doubt-clearing sessions are held every week.`},{q:`What happens if I miss a class?`,a:`Every live session is recorded and available 24/7 in your student portal. You can also attend the same topic in a parallel batch or bring questions to the weekly doubt-clearing session.`},{q:`Is there a certificate on completion?`,a:`Yes. On completing the program and capstone project, you receive an industry-recognized Full Stack Developer certification from Nirayush EduTech, which you can add to your resume and LinkedIn.`},{q:`What is the refund policy?`,a:`If you decide the program is not for you within the first 7 days of classes, you are eligible for a full refund, no questions asked. After that, refunds are prorated as per the enrollment agreement.`},{q:`How is the scholarship calculated?`,a:`Scholarships are merit-based, primarily on your academic record — students with 7+ CGPA (or equivalent) qualify for up to 25% off the program fee. Slots are limited per batch and awarded after a short interview.`}];function d(){let[e,t]=(0,s.useState)(0);return(0,l.jsx)(`section`,{id:`faq`,className:c.section,children:(0,l.jsxs)(`div`,{className:`container`,children:[(0,l.jsxs)(a,{className:c.head,children:[(0,l.jsxs)(`span`,{className:`section-tag`,children:[(0,l.jsx)(`i`,{className:`fa-solid fa-circle-question`,style:{marginRight:`.4rem`}}),`FAQ`]}),(0,l.jsxs)(`h2`,{className:`section-title`,children:[`Frequently Asked `,(0,l.jsx)(`span`,{className:`grad`,children:`Questions`})]}),(0,l.jsx)(`p`,{className:`section-desc`,children:`Everything you need to know before joining. Still have questions? Reach out below.`})]}),(0,l.jsx)(a,{className:c.list,children:u.map((n,a)=>{let s=e===a;return(0,l.jsxs)(`div`,{className:`${c.item} ${s?c.itemOpen:``}`,children:[(0,l.jsxs)(`button`,{className:c.question,onClick:()=>t(s?-1:a),"aria-expanded":s,children:[(0,l.jsx)(`span`,{children:n.q}),(0,l.jsx)(`i`,{className:`fa-solid fa-chevron-down ${c.chevron}`})]}),(0,l.jsx)(r,{initial:!1,children:s&&(0,l.jsx)(i.div,{className:c.answerInner,initial:{height:0,opacity:0},animate:{height:`auto`,opacity:1},exit:{height:0,opacity:0},transition:{duration:.4,ease:o},children:(0,l.jsx)(`p`,{className:c.answer,children:n.a})})})]},n.q)})})]})})}export{d as t};